// Des: Tests for ct-expo-data: JSONL and CSV, escaping, formula guard
// Flo: insert rows with nasty text > export > parse back / compare
// I/O: rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const expo = @import("ct-expo-data.zig"); const inde = @import("st-page-inde.zig");
const allo = std.testing.allocator;
fn seed(dbzz: *@import("st-stor-sqli.zig").Dbzz) !void { const rowz: inde.Rowz = .{ .hexz = "aa", .etag = "", .lmod = "", .code = 200, .tier = 1, .vend = "", .fetc = 5, .next = 9 }; try inde.pageSetz(dbzz, "http://a/1", rowz); try inde.pageSetz(dbzz, "http://a/2", rowz); try inde.recoSetz(dbzz, "http://a/1", .{ .hexz = "aa", .kind = "text", .body = "line \"one\"\nline,two" }, 1); try inde.recoSetz(dbzz, "http://a/2", .{ .hexz = "aa", .kind = "ldjs", .body = "=HYPERLINK(\"x\")" }, 1); }
test "JSONL: one valid JSON object per record, newlines escaped" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); try seed(&dbzz); var wtrz = std.Io.Writer.Allocating.init(allo); defer wtrz.deinit(); const con2 = try expo.expoRunz(&dbzz, &wtrz.writer, .jso2, allo); try std.testing.expectEqual(@as(u64, 2), con2); var lin2 = std.mem.splitScalar(u8, std.mem.trimEnd(u8, wtrz.written(), "\n"), '\n'); var got2: usize = 0; while (lin2.next()) |line| { var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const val2 = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), line, .{}); try std.testing.expect(val2.object.get("urlz") != null); got2 += 1; } try std.testing.expectEqual(@as(usize, 2), got2); }
test "CSV: header, quoting, doubled quotes, formula guard" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); try seed(&dbzz); var wtrz = std.Io.Writer.Allocating.init(allo); defer wtrz.deinit(); _ = try expo.expoRunz(&dbzz, &wtrz.writer, .csv, allo); const text = wtrz.written(); try std.testing.expect(std.mem.startsWith(u8, text, "urlz,kind,hexz,tier,vend,fetc,body\n")); try std.testing.expect(std.mem.indexOf(u8, text, "\"line \"\"one\"\"\nline,two\"") != null); try std.testing.expect(std.mem.indexOf(u8, text, "\"'=HYPERLINK(\"\"x\"\")\"") != null); }
test "empty store exports nothing (CSV keeps the header)" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); defer allo.free(dirz); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var wtrz = std.Io.Writer.Allocating.init(allo); defer wtrz.deinit(); try std.testing.expectEqual(@as(u64, 0), try expo.expoRunz(&dbzz, &wtrz.writer, .jso2, allo)); try std.testing.expectEqual(@as(usize, 0), wtrz.written().len); }
